targets.expr:
max by (job,instance) (
  system_uptime_seconds{job=~".+",job=~"$job",instance=~"$instance"}
)
or
max by (job,instance) (
  system_uptime{job=~".+",job=~"$job",instance=~"$instance"}
)

max by (job,instance,host_name) (
  target_info{job=~".+",job=~"$job",instance=~"$instance", host_name!=""}
)

max by (job,instance,os_name) (
  label_replace(target_info{job=~".+",job=~"$job",instance=~"$instance", os_description!=""}, "os_name", "$1", "os_description", "(.+?)( [(].*)?")
)

max by (job,instance) (
  system_cpu_load_average_1m{job=~".+",job=~"$job",instance=~"$instance"}
)

max by (job,instance) (
  system_cpu_logical_count{job=~".+",job=~"$job",instance=~"$instance"}
)

max by (job,instance) (
  system_memory_limit_bytes{job=~".+",job=~"$job",instance=~"$instance"}
)
or
max by (job,instance) (
  system_memory_limit{job=~".+",job=~"$job",instance=~"$instance"}
)

100 * (
  sum by (job,instance) (
  system_memory_utilization_ratio{job=~".+",job=~"$job",instance=~"$instance", state="used"}
)
)
or
100 * (
  sum by (job,instance) (
  system_memory_utilization{job=~".+",job=~"$job",instance=~"$instance", state="used"}
)
)

sum by (job,instance) (
  system_filesystem_usage_bytes{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mountpoint="/"}
)
or
sum by (job,instance) (
  system_filesystem_usage{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mountpoint="/"}
)

100 * (
  max by (job,instance) (
  system_filesystem_utilization_ratio{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mountpoint="/"}
)
)
or
100 * (
  max by (job,instance) (
  system_filesystem_utilization{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mountpoint="/"}
)
)

count by (job,instance) (
  ALERTS{alertstate="firing", severity="critical", job=~".+",job=~"$job",instance=~"$instance"}
)

count by (job,instance) (
  ALERTS{alertstate="firing", severity="warning", job=~".+",job=~"$job",instance=~"$instance"}
)

topk(25,
  100 * (
  sum by (job,instance) (
  system_memory_utilization_ratio{job=~".+",job=~"$job",instance=~"$instance", state="used"}
)
)
)
or
topk(25,
  100 * (
  sum by (job,instance) (
  system_memory_utilization{job=~".+",job=~"$job",instance=~"$instance", state="used"}
)
)
)

topk(25,
  max by (job,instance) (
  system_cpu_load_average_1m{job=~".+",job=~"$job",instance=~"$instance"}
)
)

topk(25,
  sum by (job,instance) (
  rate(system_disk_io_bytes_total{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)
or
topk(25,
  sum by (job,instance) (
  rate(system_disk_io{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)

topk(25,
  100 * (
  max by (job,instance,mountpoint) (
  system_filesystem_utilization_ratio{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mode!="ro"}
)
)
)
or
topk(25,
  100 * (
  max by (job,instance,mountpoint) (
  system_filesystem_utilization{job=~".+",job=~"$job",instance=~"$instance", type!="", mountpoint!="", mode!="ro"}
)
)
)

topk(25,
  sum by (job,instance) (
  rate(system_network_io_bytes_total{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)
or
topk(25,
  sum by (job,instance) (
  rate(system_network_io{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)

topk(25,
  sum by (job,instance) (
  rate(system_network_errors_total{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)
or
topk(25,
  sum by (job,instance) (
  rate(system_network_errors{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)

topk(25,
  sum by (job,instance) (
  rate(system_network_dropped_total{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)
or
topk(25,
  sum by (job,instance) (
  rate(system_network_dropped{job=~".+",job=~"$job",instance=~"$instance", device!=""}[$__rate_interval])
)
)

max by (job,instance) (
  system_uptime_seconds{job=~".+",job=~"$job",instance=~"$instance"}
)
or
max by (job,instance) (
  system_uptime{job=~".+",job=~"$job",instance=~"$instance"}
)
